function updateProductMenu(){const menu=document.querySelector('.product-menu');if(!menu)return;const isKeyboard=location.pathname.endsWith('/configure.html');let selected=location.pathname.endsWith('/mouse.html')?'mouse':null;if(isKeyboard){try{selected=JSON.parse(new URLSearchParams(location.search).get('build')||'{}').m==='mountain'?'mountain':'character';}catch{selected='character';}}menu.classList.toggle('product-menu--compact',location.pathname!=='/'&&!location.pathname.endsWith('/index.html'));menu.querySelectorAll('[data-menu-product]').forEach(a=>{if(a.dataset.menuProduct===selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}updateProductMenu();document.addEventListener('keyboard-model-change',()=>setTimeout(updateProductMenu,0));document.addEventListener('change',()=>setTimeout(updateProductMenu,0));addEventListener('popstate',updateProductMenu);